  const childEnvironment = {};
  const seen = new Map();

  for (const [key, value] of Object.entries(environment)) {
    const normalized = platform === "win32" ? key.toUpperCase() : key;
    if (unsafeLauncherVariables.has(normalized)) continue;

    if (platform === "win32") {
      const previous = seen.get(normalized);
      if (previous !== undefined) {
        if (previous.value !== value) {
          throw new Error(`Conflicting case-insensitive Windows environment values exist for ${key}.`);
        }
        continue;
      }
      seen.set(normalized, { value });
    }
    childEnvironment[key] = value;
  }

  for (const name of ["GB_STUDIO_RUNTIME_ROOT", "GB_STUDIO_TOOLCHAIN_ROOT", "GB_STUDIO_PLUGIN_ROOT"]) {
    deleteEnvironmentAliases(childEnvironment, name, platform);
  }
  childEnvironment.GB_STUDIO_RUNTIME_ROOT = runtimeRoot;
  childEnvironment.GB_STUDIO_PLUGIN_ROOT = pluginRoot;

  const configuredToolchain = readEnvironment(environment, "GB_STUDIO_TOOLCHAIN_ROOT", platform)?.trim();
  childEnvironment.GB_STUDIO_TOOLCHAIN_ROOT = configuredToolchain
    ? path.resolve(workingDirectory, configuredToolchain)
    : defaultToolchainRoot;

  // The host replaces cwd before launching cached plugins. Only explicitly
  // configured roots can authorize a workspace; the runtime checkout never can.
  for (const variable of ["GB_STUDIO_WORKSPACE_ROOT", "GB_STUDIO_PROJECT_ROOT"]) {
    const configuredRoot = readEnvironment(environment, variable, platform)?.trim();
    deleteEnvironmentAliases(childEnvironment, variable, platform);
    if (configuredRoot) {
      childEnvironment[variable] = path.resolve(workingDirectory, configuredRoot);
    }
  }

  return childEnvironment;
}

function resolvePreparedRuntime(candidate) {
  const candidateServerPath = path.join(candidate, "dist", "server.js");

  try {
    if (!statSync(candidateServerPath).isFile()) {
      return undefined;
    }
            continue
        try:
            resolved_executable = executable.resolve(strict=True)
        except (OSError, RuntimeError):
            continue
        if not any(resolved_executable.is_relative_to(root) for root in rejected_roots):
            return resolved_executable

    raise FileNotFoundError(
        "Plugin registration requires an installed Node.js executable "
        "in a trusted absolute PATH directory."
    )


def executable_rejected_roots(source: Path, runtime_root: Path, toolchain_root: Path, user_home: Path) -> list[Path]:
    roots = {source, runtime_root, toolchain_root}
    for selected in list(roots):
        local = selected / ".local"
        if local.exists():
            roots.add(local.resolve(strict=True).parent)
    for name in ("GB_STUDIO_WORKSPACE_ROOT", "GB_STUDIO_PROJECT_ROOT"):
        configured = os.environ.get(name, "").strip()
        if configured:
            selected = Path(configured).expanduser().resolve(strict=False)
            roots.add(selected.parent if selected.is_file() else selected)
    current = Path.cwd().resolve(strict=True)
    if current != user_home and current != Path(current.anchor):
        roots.add(current)
    return list(roots)


def remove_directory_link(candidate: Path) -> None:
    if candidate.is_symlink():
        candidate.unlink()
    elif is_directory_junction(candidate):
        candidate.rmdir()
    else:
        raise ValueError(f"Refusing to remove existing non-link plugin path: {candidate}")


def create_windows_junction(source: Path, destination: Path, node: Path, user_home: Path) -> None:
```text
project_create {"name":"My Game","destinationPath":"/absolute/existing-parent/MyGame","template":"starter"}
```

The minimal `starter` is included. Choose `template: "wrecklight"` for a complete
editable salvage adventure; in a compact installation, supply its matching local
`templateSourcePath`. Follow the [remix guide](../../../docs/wrecklight-remix.md)
for its engine version, controls, and credits. Both bundled Wrecklight copies
are read-only; `allowStarter` does not permit selecting them directly.

This authorizes only the created `MyGame` project, not its parent or siblings.
It remains unselected unless `select: true` is explicit; otherwise select the
returned project descriptor before authoring or building.

For sibling projects, configure their common `GB_STUDIO_WORKSPACE_ROOT` before
server startup. It authorizes a fixed workspace without selecting a project;
creation, discovery, and selection may then use paths relative to it:

```text
project_discover {"projectPath":"games/MyGame/MyGame.gbsproj"}
project_select {"projectPath":"games/MyGame/MyGame.gbsproj"}
```

Discovery never authorizes or selects a project; attempting the relative flow
without an authorized workspace fails closed, including relative creation.
Neither create nor select calls expand an existing authorization boundary.
`GB_STUDIO_PROJECT_ROOT` explicitly selects the configured descriptor or
project directory; without a separately authorized workspace its authority
ends at that directory.
Unselected project operations fail with `PROJECT_SELECTION_REQUIRED`. Selecting
the bundled starter requires `allowStarter: true`; `project_create` instead

